#include <list>
#include <unordered_map>
#include <bitset>
#include <algorithm>
#define ll long long int
#define e() cout << endl;
#define MA INT_MAX
#define MI INT_MIN
#define MOD 1000000007;
#define ppi pair <int,int>
#define scn(n) scanf("%d",&n)
#define vvi(n,m,x) vector <vector <int> > v(n,vector <int> (m,x));
#define cp(x,y) cout << "Case : " << x << " " << y << endl;
using namespace std;
int main()
{
	string s,x = "";
	bool ok = true;
	cin >> s;
	for(int i = 0;i < s.size();)
	{
		if(s.substr(i,3) == "dot")
			x += '.',i += 3;
		else if(s.substr(i,2) == "at" && ok && i) 
			x += '@',i += 2,ok = false;
		else
			x += s[i],i++;
	}
	for(int i = 0;i < x.size();i++)
		if(i == 0 && x[i] == '.')
			cout << "dot";
		else if(i == 0 && x[i] == '@')
			cout << "at";
		else if(i == x.size() - 1 && x.back() == '@')
			cout << "at";
		else if(i == x.size() - 1 && x.back() == '.')
			cout << "dot";
		else
			cout << x[i];
	e();
	return 0;	
}
